class QxdmLogsCollector(object):
    def __init__(self, script_name='QXDM5LogCatch.py', ue_pc_dir_path='c:/auto/'):
        self.script_name = script_name
        self.ue_pc_dir_path = ue_pc_dir_path
        self.ue_pc_logs_dir = os.path.join(self.ue_pc_dir_path, 'logs')
        self.script_path = os.path.join(self.ue_pc_dir_path, self.script_name)
        self._hdf_log_file = None
        self._txt_log_file = None
        self._start_cmd = None
        self._ute_ue_config = get_yaml_ue_config()

    @load_moler_configuration_from_tl()
    def upload_qxdmlogcatch_script(self, ue_id=0):
        """
        Upload QXDM5LogCatch.py to UE PC.
        QXDM5LogCatch.py allows collect QXDM logs and save it to *.hdf format.
        :param ue_id: ID of UE
        :return: None
        """
        upload_files(local_dir=self._get_scripts_dir_path(),
                     local_file=self.script_name,
                     remote_dir=WindowsUePcUtil.convert_to_cygpath(self.ue_pc_dir_path),
                     device_name=device_aliases.ue_pc.format(ue_id),
                     )

    def collect_qxdm_hdf_log(self, log_file=None, ue_id=0, duration=60, dmc_file=None, com_port=None,
                             python_path=None, ue_chip_name=None):
        """
        Keyword for start collecting QXDM hdf log in the background.

        :param ue_id:               UE id - related to Test Line configuration - tl.ues.
        :param dmc_file:            path to dmc configuration file
        :param com_port:            UE COM port number(s) eg: `COM9` or `COM4,COM7` in case two ports assigned to UE device or for QXDM5 could be 'MDM'
        :param log_file:            path to log
        :param duration:            duration of collecting log
        :param python_path:         path to python eg: ''C:/Python27/python.exe''
        :param ue_chip_name:        chip name of UE eg: 'SDX55', 'SDX60', 'SDX75'
        :return: None
        Sample Android configuration from __init__.py
        _android_ue = Android(
            ssh_connection_details=_ue_pc_ssh,
            serial_number="7d586bb0",
            server_dir="/cygdrive/c/pyro_server",
            python_path="C:/Python27/python.exe",
            qcat_path="C:/Program Files (x86)/Qualcomm/QCAT 6.x/Bin/QCAT.exe",
            diag_cfg_path="C:/pyro_server/DIAG.cfg",
            dmc_path="c:/usb/Config-4G-5G-SDx55-RFP_v0.4.dmc",
            diag_com="MDM",
            iperf_details=_android_iperf,
            capabilities=["REAL_ANDROID_UE"],
        )
        """
        if not log_file:
            log_file = os.path.join(self.ue_pc_logs_dir, 'qxdm.hdf')

        if not python_path:
            python_path = self._get_python_path_from_config(ue_id)

        if not com_port:
            com_port = self._get_com_port_from_config(ue_id)

        if not dmc_file:
            dmc_file = self._get_dmc_file_from_config(ue_id)

        self._hdf_log_file = log_file

        if ue_chip_name is None:
            cmd = "{} {} -t {} -p {} -c {} -s {}".format(python_path, self.script_path, duration,
                                                         com_port, dmc_file, self._hdf_log_file)
        else:
            cmd = "{} {} -t {} -p {} -c {} -s {} -cn {}".format(python_path, self.script_path, duration,
                                                                com_port, dmc_file, self._hdf_log_file, ue_chip_name)

        self._start_cmd = WindowsUePcUtil.execute_ue_pc_cmd(ue_id=ue_id, cmd=cmd, timeout=int(duration) + 20,
                                                            background=True,
                                                            error_regex=re.compile(r'(Fail to connect port COM)|'
                                                                                   r'(Unable to obtain ISF interface)|'
                                                                                   r'(Unable to load the dmc)|'
                                                                                   r'(chipName parameter is required for number COM ports > 1)'))

    def cancel_collecting_qxdm_hdf_log(self):
        """
        It's should be used if you would like force cancel collecting qxdm log.
        """
        self._start_cmd.cancel()

    def wait_till_collecting_qxdm_hdf_log_is_finished(self):
        """
        Wait when collecting hdf logs is finished.
        :return:
        """
        self._start_cmd.await_done()

    def convert_hdf_log_to_txt(self, hdf_log=None, ue_id=0, qcat_path=None, filter_file=None, timeout=120):
        """
        Keyword for converting hdf log to txt format.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues
        :param hdf_log:         path to hdf log
        :param qcat_path:       path to QCAT.exe eg: ''C:/Program Files (x86)/Qualcomm/QCAT 6.x/Bin/QCAT.exe''
        :param filter_file:     path to filter.txt file eg: ''C:/filter.txt''. Filter file can be generated manually
                                using QCAT application.
        :param timeout:         timeout for converting isf --> txt
        """
        if not qcat_path:
            qcat_path = self._get_qcat_path_from_config(ue_id)
        if not hdf_log:
            hdf_log = self._hdf_log_file

        self._txt_log_file = hdf_log.replace('.hdf', '.txt')

        if filter_file is None:
            cmd = "'{}' -txt '{}'".format(qcat_path, hdf_log)
        else:
            cmd = "'{}' -txt -filter='{}' '{}'".format(qcat_path, filter_file, hdf_log)

        try:
            WindowsUePcUtil.execute_ue_pc_cmd(ue_id=ue_id, cmd=cmd, timeout=timeout)
        except CommandFailure as e:
            if r'The remote server returned an error: (404) Not Found' not in repr(e):
                raise e

        return self._txt_log_file

    def download_qxdm_logs(self, download_dir=None, log_file=None, ue_id=0, timeout=60):
        """
        Download all logs from UE_PC to local PC.

        :param download_dir: path to directory where file will be downloaded. If not passed Robot
                             output dir will be used.
        :param log_file:     path to logs located on UE_PC - could pass many separated by comma
        :param ue_id:        UE id - related to Test Line configuration - tl.ues.
        :param timeout:      timeout for downloading file
        """

        if download_dir is None:
            download_dir = get_builtin_value('OUTPUT DIR')

        if log_file is None:
            log_file = ",".join([os.path.basename(self._hdf_log_file), os.path.basename(self._txt_log_file)])
            remote_dir = os.path.dirname(self._hdf_log_file)
        else:
            files = log_file.split(',')
            remote_dir = os.path.dirname(files[0])
            log_file = ','.join([os.path.basename(file_path) for file_path in files])

        download_files(local_dir=download_dir,
                       remote_file=log_file,
                       remote_dir=remote_dir,
                       device_name=device_aliases.ue_pc.format(ue_id),
                       remove_source_file=True,
                       timeout=timeout
                       )

    def kill_all_qxdm_processes(self, ue_id=0):
        """
        Keyword for kill QXDM.exe process.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        """
        self.kill_qxdm_process(ue_id=ue_id)
        self.kill_qxdm_server_process(ue_id=ue_id)

    @staticmethod
    def kill_qxdm_process(ue_id=0):
        """
        Keyword for kill QXDM.exe process.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        """
        WindowsUePcUtil.kill_ue_pc_process(process_name="QXDM.exe", ue_id=ue_id)

    @staticmethod
    def kill_qcat_process(ue_id=0):
        """
        Keyword for kill QCAT.exe process.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        """
        WindowsUePcUtil.kill_ue_pc_process(process_name="QCAT.exe", ue_id=ue_id)

    @staticmethod
    def kill_qxdm_server_process(ue_id=0):
        """
        Keyword for kill QPSTServer.exe process.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        """
        WindowsUePcUtil.kill_ue_pc_process(process_name="QPSTServer.exe", ue_id=ue_id)

    @staticmethod
    def kill_quts_process(ue_id=0):
        """
        Keyword for kill QUTSService.exe process.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        """
        WindowsUePcUtil.kill_ue_pc_process(process_name="QUTSService.exe", ue_id=ue_id)

    @load_moler_configuration_from_tl()
    def clear_log_directory(self, log_dir=None, ue_id=0):
        """
        Keyword for clear log directory on UE PC.

        :param ue_id:       UE id - related to Test Line configuration - tl.ues.
        :param log_dir:     log directory path to clear
        :return: None
        """
        if log_dir is None:
            log_dir = self.ue_pc_logs_dir
        ue_pc_device_name = device_aliases.ue_pc.format(ue_id)
        ue_pc = DeviceFactory.get_device(name=ue_pc_device_name)
        rm = ue_pc.get_cmd(cmd_name="rm", cmd_params={'file': os.path.join(log_dir, "*"), 'options': '-rf'})
        rm()

    @staticmethod
    def _get_scripts_dir_path():
        current_dir = os.path.dirname(os.path.abspath(__file__))
        config_dir = os.path.abspath(os.path.join(current_dir, '..', 'scripts'))
        return config_dir

    def _get_python_path_from_config(self, ue_id):
        if self._ute_ue_config:
            python_path = get_ue_configuration(ue_id, self._ute_ue_config)['server_python']

        else:
            python_path = get_builtin_value('tl.ues[{}].python_path'.format(ue_id))
        return python_path

    def _get_com_port_from_config(self, ue_id):
        if self._ute_ue_config:
            com_port = get_ue_configuration(ue_id, self._ute_ue_config)['diag_com']
        else:
            com_port = get_builtin_value('tl.ues[{}].diag_com'.format(ue_id))
        return com_port

    def _get_dmc_file_from_config(self, ue_id):
        if self._ute_ue_config:
            dmc_file = get_ue_configuration(ue_id, self._ute_ue_config)['dmc_path']
        else:
            dmc_file = get_builtin_value('tl.ues[{}].dmc_path'.format(ue_id))
        return dmc_file

    def _get_qcat_path_from_config(self, ue_id):
        if self._ute_ue_config:
            qcat_path = get_ue_configuration(ue_id, self._ute_ue_config)['qcat_exe_path']
        else:
            qcat_path = get_builtin_value('tl.ues[{}].qcat_path'.format(ue_id))
        return qcat_path


class LicenseKeeperKeywords(object):
    CLIENT_MAIN = "ClientMain.exe"

    def __init__(self, alias='lkc', login=None, password=None):
        self.alias = alias
        self.lkc = licence_keeper()
        self.login = login
        self.password = password
        self._ute_ue_config = get_yaml_ue_config()

    def connect_to_license_keeper_client(self, login=None, password=None, lkc_path='/cygdrive/c/QPM_LK1.4',
                                         port=6006, ue_id=0):
        """
        Start client and log to the server.

        :param login:       login to license keeper - eg. name.surname@nokia.com.
        :param password:    password to license keeper
        :param lkc_path:    path to license keeper client located on UEPC.
        :param port:        license keeper client port.
        :param ue_id:       UE id - related to Test Line configuration - tl.ues.
        """
        if login and password:
            self.login = login
            self.password = password
        elif (self.login is None or self.login is None) and (login is None or password is None):
            credentials = self._get_credentials_from_file(file_path=os.path.join(lkc_path, 'credentials.yaml'),
                                                          ue_id=ue_id)
            self.login = credentials['user']
            self.password = credentials['password']

        if self._ute_ue_config:
            ue_config = get_ue_configuration(ue_id, self._ute_ue_config)
            host = ue_config.get('ue_pc_address', ue_config.get('ue_pc_ip'))
            username = ue_config.get('ue_pc_login', ue_config.get('login'))
            ue_pc_password = ue_config.get('ue_pc_password', ue_config.get('password'))
        else:
            host, username, ue_pc_password = get_ue_pc_credentials(ue_id)
        # Commented due to issue with starting application -
        # Please ensure the QPM_LK client is running already before the testing.
        #
        # self.kill_lk_client(ue_id=ue_id)
        # self.start_lk_client(lkc_path=lkc_path, ue_id=ue_id)
        # time.sleep(30)

        self.lkc.setup(launcher={'host': host, 'user': username, 'password': ue_pc_password, 'path': lkc_path},
                       port=port, alias=self.alias)
        self.lkc.login(username=self.login, password=self.password, client=self.alias)

    @staticmethod
    def start_lk_client(lkc_path, ue_id=0):
        """
        Start License Keeper ClientMain.exe

        :param lkc_path:    path to license keeper client located on UEPC.
        :param ue_id:       UE id - related to Test Line configuration - tl.ues.
        :return: None
        """
        # TODO  Need to handle  "Do you want to allow this app from unknown publisher to make changes to your device"
        cmd = "cd {};./{} &".format(lkc_path, LicenseKeeperKeywords.CLIENT_MAIN)
        WindowsUePcUtil.execute_ue_pc_cmd(cmd=cmd, ue_id=ue_id)

    @staticmethod
    def kill_lk_client(ue_id=0):
        """
        Kill ClientMain.exe process.

        :param ue_id:       UE id - related to Test Line configuration - tl.ues.
        :return: None
        """
        WindowsUePcUtil.kill_ue_pc_process(process_name=LicenseKeeperKeywords.CLIENT_MAIN, ue_id=ue_id)

    def get_qxdm_and_qcat_licence(self):
        """
        Get 5G QXDM and QCAT License
        """
        self.lkc.get_licence_qxdm_5g(client=self.alias)
        self.lkc.get_licence_qcat_5g(client=self.alias)

    def release_qxdm_and_qcat_licence(self):
        """
        Release QXDM and QCAT license.
        """

        self._release_licence(release_method=self.lkc.release_licence_qxdm_5g)
        self._release_licence(release_method=self.lkc.release_licence_qcat_5g)
        self.lkc.logout(client=self.alias)
        self.lkc.teardown(client=self.alias)

    def get_pcat_licence(self):
        """
        Get 5G PCAT License
        """
        self.lkc.get_licence_pcat_5g(client=self.alias)

    def release_pcat_licence(self, close_connection=True):
        """
        Release PCAT license.
        :param close_connection: defines whether the connection to lkc should be closed
        """

        self._release_licence(release_method=self.lkc.release_licence_pcat_5g)
        if close_connection:
            self.lkc.logout(client=self.alias)
            self.lkc.teardown(client=self.alias)

    def _release_licence(self, release_method):
        try:
            release_method(client=self.alias)
        except Exception as e:
            logging.warn("{}: {}".format(release_method.__name__, repr(e)))

    @staticmethod
    @load_moler_configuration_from_tl()
    def _get_credentials_from_file(file_path='/cygdrive/c/QPM_LK1.4/credentials.yaml', ue_id=0):
        """
        Read configuration file located on UEPC and return dict.

        :param ue_id:                   UE id - related to Test Line configuration - tl.ues.
        :param file_path:               path to file with credentials located on UE_PC
        :return: credentials:           dict

        credentials.yaml file should be in format as below:
        user: project_account@nokia.com
        password: GiveMeLicence
        """
        ue_pc_device_name = device_aliases.ue_pc.format(ue_id)
        ue_pc = DeviceFactory.get_device(name=ue_pc_device_name)
        cat = ue_pc.get_cmd(cmd_name="cat", cmd_params={'path': file_path})
        file_content = cat()
        credentials = yaml.load("\n".join(file_content['LINES']), Loader=yaml.FullLoader)
        return credentials


class WindowsUePcUtil(object):
    @staticmethod
    def convert_to_cygpath(dir_path):
        """

        :param dir_path: path in Windows nomenclature
        :return: path with cgdrive prefix
        """
        return dir_path.replace('c:', '/cygdrive/c')

    @staticmethod
    @load_moler_configuration_from_tl()
    def execute_ue_pc_cmd(ue_id, cmd, timeout=60, error_regex=re.compile("error", re.IGNORECASE), background=False):
        """
        Execute any Windows command on UEPC device.

        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        :param cmd:             Command to execute
        :param timeout:         Command timeout
        :param error_regex:     Regex for failure command
        :param background:      True/False - run command in the background
        :return: None
        """
        ue_pc_device_name = device_aliases.ue_pc.format(ue_id)
        ue_pc = DeviceFactory.get_device(name=ue_pc_device_name)
        time.sleep(0.5)
        _cmd = ue_pc.get_cmd(cmd_name="run_script", cmd_params={'script_command': cmd,
                                                                'error_regex': error_regex})
        if background:
            _cmd.start(timeout=timeout)
            return _cmd
        else:
            _cmd(timeout=timeout)
            time.sleep(0.5)

    @classmethod
    def kill_ue_pc_process(cls, process_name, ue_id=0):
        """
        Kill process cia TASKKILL windows command
        :param process_name:    name of process to KILL
        :param ue_id:           UE id - related to Test Line configuration - tl.ues.
        :return: None
        """
        try:
            cls.execute_ue_pc_cmd(ue_id=ue_id, cmd="taskkill /F /IM {}".format(process_name))
        except CommandFailure as error:
            if 'ERROR: The process "{}" not found.'.format(process_name) in repr(error):
                logging.debug("{} process not exists".format(process_name))
            else:
                raise error
